function latestMovement(a:Asset){const movement=events.filter(e=>e.assetId===a.id&&e.effectiveDate&&['Registered','Assigned','Reassigned','Returned','Repair flagged','Repair completed','Reported lost','Retired','Made available','Return reverted'].includes(e.action)).sort((x,y)=>y.date.localeCompare(x.date))[0];let label=movement?.action||'',date=movement?.effectiveDate||'';if(label==='Assigned'||label==='Reassigned')label='Issued';if(label==='Returned'&&movement.reason?.startsWith('Equipment replacement:'))label='Replaced';if(label==='Return reverted')label='Assignment restored';if(label==='Registered'&&movement.after?.status==='Assigned'){label='Issued';date=movement.after.currentAssignmentDate||date}if(!movement&&a.status==='Assigned'){label='Issued';date=a.currentAssignmentDate||''}if(!movement&&a.status==='Returned'){label='Returned';date=a.lastReturnDate||''}return <><span>{label||'—'}</span>{date&&<small>{new Date(date+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</small>}{label&&!date&&<small>Date not recorded</small>}</>}
