async function save(e:React.FormEvent){e.preventDefault();if(!edit)return;if(!edit.category.trim()){setError('Select an Equipment Type before saving.');return}if(acquisitionLabel(edit)==='Accessory Allowance'&&edit.receiptReference){const balanceError=allowanceCashError(edit.itemValue,edit.promotionalCreditUsed,edit.purchaseCost);if(balanceError){setError(balanceError);return}}setSaving(true);setError('');setMessage('');try{let d:any;try{d=await readApiResponse(await fetch('/api/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(edit)}))}catch(e:any){if(e.code!=='DUPLICATE_SERIAL')throw e;if(!window.confirm(e.message+'\n\nSave anyway? Only continue if this serial number legitimately belongs to more than one item.'))return;d=await readApiResponse(await fetch('/api/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...edit,allowDuplicateSerial:true})}))}const action=edit.isNew?'Asset Registered':edit.status==='Assigned'&&(baseline?.status!=='Assigned'||baseline?.assignee!==edit.assignee)?'Equipment Assigned':'Asset Saved';setEdit(null);await load();setMessage(action+' — '+edit.id+'.')}catch(e:any){setError(e.message)}finally{setSaving(false)}}
